class MessageService {
    client;
    constructor(client) {
        this.client = client;
    }
    async postSend(request) {
        return new Promise((resolve, reject) => {
            this.client
                .post('/v1/messages/send', request)
                .then((response) => {
                resolve(response.data.data);
            })
                .catch(async (error) => {
                reject(error);
            });
        });
    }
}
export default MessageService;
